<template>
  <div class="assistant-page">
    <button class="assistant-mobile-history" type="button" @click="mobileHistoryOpen=true"><el-icon><Clock /></el-icon>会话</button>
    <aside class="chat-sidebar section-card">
      <div class="chat-sidebar__new"><el-button type="primary" @click="newConversation"><el-icon><Plus /></el-icon> 新对话</el-button></div>
      <div class="chat-sidebar__label">对话历史</div>
      <div class="conversation-list"><button v-for="conv in conversations" :key="conv.id" :class="['conv-item',{active:conv.id===currentConvId}]" type="button" @click="switchConversation(conv.id)"><el-icon><ChatDotRound /></el-icon><span><strong>{{ conv.title||'新对话' }}</strong><small>{{ formatTime(conv.last_active) }}</small></span><el-icon class="conv-delete" @click.stop="deleteConversation(conv.id)"><Delete /></el-icon></button><StatusState v-if="!conversations.length" type="empty" title="暂无历史会话" /></div>
      <div class="assistant-templates"><div class="chat-sidebar__label">助手模板</div><button v-for="item in templates" :key="item.title" type="button" @click="sendMessage(item.question)"><span :class="item.tone"><el-icon><component :is="item.icon" /></el-icon></span><div><strong>{{ item.title }}</strong><small>{{ item.description }}</small></div></button></div>
    </aside>

    <main class="chat-main section-card">
      <div class="message-list" ref="messageListRef">
        <section v-if="messages.length===0" class="assistant-welcome">
          <img :src="assistantHero" alt="蓝白智能机器人与淡雅传统亭阁" />
          <div><span class="eyebrow">HERITAGE AI RESEARCH</span><h1>您好，我是遗址公园智能助手</h1><p>我可以帮您查询数据、分析对比、解读知识并生成研究参考。</p></div>
        </section>
        <section v-if="messages.length===0" class="quick-question-section"><div class="quick-question-section__title"><h2>您可以试着问我</h2><button type="button" @click="rotateQuestions"><el-icon><Refresh /></el-icon>换一换</button></div><div class="quick-questions"><button v-for="question in visibleQuestions" :key="question" type="button" @click="sendMessage(question)">{{ question }}<el-icon><ArrowRight /></el-icon></button></div></section>
        <ChatMessage v-for="(msg,index) in messages" :key="index" :msg="msg" @retry="retryMessage(index)" />
        <div ref="scrollAnchor"></div>
      </div>
      <div class="input-area"><el-input v-model="inputText" placeholder="输入您的问题，Enter 发送；Shift + Enter 换行" :rows="2" type="textarea" resize="none" :disabled="isStreaming" @keydown.enter.exact.prevent="sendMessage()"/><div class="input-area__actions"><span>回答基于平台当前可用数据与知识</span><el-button v-if="!isStreaming" type="primary" :disabled="!inputText.trim()" aria-label="发送问题" @click="sendMessage()"><el-icon><Promotion /></el-icon></el-button><el-button v-else type="danger" aria-label="停止生成" @click="stopStreaming"><el-icon><Close /></el-icon></el-button></div></div>
    </main>

    <aside class="assistant-context">
      <section class="section-card"><div class="section-card__header"><div><h2>当前关联模块</h2></div><router-link to="/library">更换</router-link></div><div class="context-module"><span><el-icon><OfficeBuilding /></el-icon></span><div><strong>遗址公园</strong><small>聚合公园基础档案、评分与空间信息</small></div></div></section>
      <section class="section-card"><div class="section-card__header"><div><h2>可调用数据</h2><p>实际可用性由接口状态决定。</p></div></div><div class="data-source-list"><router-link v-for="item in dataSources" :key="item.path" :to="item.path"><el-icon><component :is="item.icon" /></el-icon><span>{{ item.title }}</span><el-icon><ArrowRight /></el-icon></router-link></div></section>
      <section class="section-card"><div class="section-card__header"><div><h2>能力说明</h2></div></div><div class="capability-list"><div v-for="item in capabilities" :key="item.title"><span><el-icon><component :is="item.icon" /></el-icon></span><div><strong>{{ item.title }}</strong><small>{{ item.description }}</small></div></div></div></section>
    </aside>

    <el-drawer v-model="mobileHistoryOpen" direction="ltr" size="min(330px,88vw)" title="对话历史" append-to-body><el-button type="primary" style="width:100%;margin-bottom:12px" @click="newConversation();mobileHistoryOpen=false"><el-icon><Plus /></el-icon>新对话</el-button><div class="mobile-conversation-list"><button v-for="conv in conversations" :key="conv.id" type="button" @click="switchConversation(conv.id);mobileHistoryOpen=false"><span>{{ conv.title||'新对话' }}</span><small>{{ formatTime(conv.last_active) }}</small></button></div></el-drawer>
  </div>
</template>

<script setup>
import { computed, nextTick, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { DataAnalysis, Search, EditPen, Collection, MapLocation, Share, Document, TrendCharts, OfficeBuilding } from '@element-plus/icons-vue'
import api from '@/utils/api'
import { streamChat } from '@/utils/sse'
import ChatMessage from '@/components/ChatMessage.vue'
import StatusState from '@/components/common/StatusState.vue'
import assistantHero from '@/assets/images/assistant-hero.webp'
const messageListRef=ref(null);const scrollAnchor=ref(null);const inputText=ref('');const isStreaming=ref(false);const messages=ref([]);const currentConvId=ref('');const conversations=ref([]);const mobileHistoryOpen=ref(false);const questionOffset=ref(0);let abortController=null
const quickQuestions=['圆明园的遗址保护情况怎么样？','城市型和乡村型公园有什么区别？','遗址保护有哪些理论和研究方法？','哪个公园的文化传播效能最好？','对比圆明园和大明宫的得分','殷墟的核心价值是什么？','当前知识库有哪些保护利用研究？','如何理解遗址公园的公众服务指标？'];const visibleQuestions=computed(()=>Array.from({length:6},(_,i)=>quickQuestions[(questionOffset.value+i)%quickQuestions.length]));const templates=[{title:'遗址研究助手',description:'研究方法与理论参考',question:'遗址公园研究有哪些常用方法？',icon:Search,tone:'violet'},{title:'数据分析助手',description:'指标与数据对比',question:'帮我分析当前遗址公园的评价数据。',icon:DataAnalysis,tone:'blue'},{title:'知识问答助手',description:'检索平台知识',question:'知识库中有哪些遗址保护主题？',icon:Collection,tone:'green'},{title:'写作助手',description:'辅助梳理研究提纲',question:'请给我一个遗址公园保护研究提纲。',icon:EditPen,tone:'orange'}];const dataSources=[{title:'遗址公园基础数据库',path:'/parks',icon:OfficeBuilding},{title:'空间地理信息',path:'/map',icon:MapLocation},{title:'知识图谱实体关系',path:'/knowledge-graph',icon:Share},{title:'研究文献知识库',path:'/library',icon:Document}];const capabilities=[{title:'数据查询与分析',description:'支持现有统计与对比数据',icon:DataAnalysis},{title:'知识问答与解读',description:'基于平台知识提供研究参考',icon:Search},{title:'报告生成与写作',description:'辅助梳理结构和内容摘要',icon:EditPen},{title:'关联研究发现',description:'串联公园、指标与文献线索',icon:TrendCharts}]
onMounted(loadConversations)
async function loadConversations(){try{const res=await api.get('/chat/conversations',{silent:true});conversations.value=res.data.conversations||[]}catch{conversations.value=[]}}
async function switchConversation(id){currentConvId.value=id;try{const res=await api.get(`/chat/history/${id}`,{silent:true});messages.value=(res.data||[]).map(msg=>({role:msg.role,content:msg.content,sources:[],chart:null,isStreaming:false}));scrollToBottom()}catch{ElMessage.error('加载对话历史失败')}}
function newConversation(){currentConvId.value='';messages.value=[]}
async function deleteConversation(id){try{await ElMessageBox.confirm('确定删除该对话？','确认');await api.delete(`/chat/conversation/${id}`);conversations.value=conversations.value.filter(item=>item.id!==id);if(currentConvId.value===id)newConversation();ElMessage.success('已删除')}catch(e){if(e!=='cancel')ElMessage.error('删除失败')}}
async function sendMessage(text){const question=text||inputText.value.trim();if(!question||isStreaming.value)return;inputText.value='';isStreaming.value=true;messages.value.push({role:'user',content:question},{role:'assistant',content:'',sources:[],chart:null,isStreaming:true});const aiIndex=messages.value.length-1;scrollToBottom();abortController=new AbortController();try{for await(const {event,data} of streamChat(question,currentConvId.value||undefined,abortController.signal)){const msg=messages.value[aiIndex];if(event==='token'){msg.content+=data.token;scrollToBottom()}if(event==='chart_data')msg.chart=data;if(event==='sources')msg.sources=data;if(event==='done'){msg.isStreaming=false;currentConvId.value=data.conversation_id||currentConvId.value;loadConversations()}if(event==='error'){msg.isStreaming=false;msg.error=data.detail||'请求失败'}}}catch(e){const msg=messages.value[aiIndex];if(e.name==='AbortError'){if(!msg.content)msg.content='（已停止生成）'}else msg.error=e.message||'网络错误，请稍后重试';msg.isStreaming=false}finally{isStreaming.value=false;abortController=null}}
function stopStreaming(){abortController?.abort()}function retryMessage(index){const msg=messages.value[index];if(!msg||msg.role!=='assistant')return;const userMsg=messages.value[index-1];messages.value.splice(index-1,2);if(userMsg?.role==='user')sendMessage(userMsg.content)}function scrollToBottom(){nextTick(()=>scrollAnchor.value?.scrollIntoView({behavior:'smooth'}))}function rotateQuestions(){questionOffset.value=(questionOffset.value+3)%quickQuestions.length}function formatTime(iso){if(!iso)return'';const date=new Date(iso);const diff=Date.now()-date;if(diff<60000)return'刚刚';if(diff<3600000)return`${Math.floor(diff/60000)}分钟前`;if(diff<86400000)return`${Math.floor(diff/3600000)}小时前`;return date.toLocaleDateString('zh-CN')}
</script>

