var(--border);border-radius:11px}.context-module>span{width:36px;height:36px;display:grid;place-items:center;border-radius:10px;color:var(--brand-600);background:var(--brand-50)}.context-module div{display:grid}.context-module strong{font-size:11px}.context-module small{margin-top:4px;color:var(--text-tertiary);font-size:8px;line-height:1.5}.data-source-list{display:grid}.data-source-list a{padding:10px 0;display:grid;grid-template-columns:auto 1fr auto;gap:8px;color:var(--text-secondary);text-decoration:none;border-bottom:1px solid var(--border);font-size:10px}.data-source-list a:hover{color:var(--brand-600)}.capability-list{display:grid;gap:12px}.capability-list>div{display:flex;gap:9px}.capability-list>div>span{width:32px;height:32px;display:grid;place-items:center;flex:0 0 auto;border-radius:9px;color:var(--brand-600);background:var(--brand-50)}.capability-list>div div{display:grid}.capability-list strong{font-size:10px}.capability-list small{margin-top:3px;color:var(--text-tertiary);font-size:8px;line-height:1.45}.assistant-mobile-history{display:none}.mobile-conversation-list{display:grid;gap:6px}.mobile-conversation-list button{padding:12px;display:grid;text-align:left;border:0;border-radius:10px;background:var(--surface-soft)}.mobile-conversation-list small{margin-top:4px;color:var(--text-tertiary)}
@media(max-width:1180px){.assistant-page{grid-template-columns:240px minmax(0,1fr)}.assistant-context{display:none}.quick-questions{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){.assistant-page{height:calc(100vh - var(--portal-header-height) - 24px);min-height:620px;display:block;position:relative}.chat-sidebar{display:none}.chat-main{height:100%}.assistant-mobile-history{display:flex;align-items:center;gap:5px;position:absolute;left:10px;top:10px;z-index:4;padding:8px 10px;border:1px solid var(--border);border-radius:9px;color:var(--brand-600);background:#fff}.message-list{padding:56px 12px 14px}.assistant-welcome{min-height:210px}.assistant-welcome img{opacity:.45;object-position:36% center}.assistant-welcome>div{width:100%;min-height:210px;padding:24px;justify-content:flex-end}.assistant-welcome h1{font-size:21px}.quick-questions{grid-template-columns:1fr}.quick-questions button{border-radius:12px}.input-area{padding:10px}.input-area__actions span{display:none}}
